    // Get a File object for the directory
    File directory = new File(dir);

    // Check if the directory exists and is a directory
    if (!directory.exists() || !directory.isDirectory()) {
        // If the directory does not exist or is not a directory, throw an IllegalArgumentException
        throw new IllegalArgumentException("The specified directory does not exist or is not a directory");
    }

    // Get a File[] of all the files in the directory
    File[] files = directory.listFiles();

    // Loop through the files and add any jar files to the classpath
    for (File file : files) {
        if (file.getName().endsWith(".jar")) {
            // Get the URL for the file and add it to the classpath Vector
            cpV.add(file.toURL());
        }
    }
}

