public String format(LoggingEvent event) {
  // 1. Throw an IllegalArgumentException if the event is null
  if (event == null) {
    throw new IllegalArgumentException("The event cannot be null");
  }

  // 2. Get the conversion pattern from the event
  String conversionPattern = event.getConversionPattern();

  // 3. Throw an IllegalArgumentException if the conversion pattern is null
  if (conversionPattern == null) {
    throw new IllegalArgumentException("The conversion pattern cannot be null");
  }

  // 4. Format the message using string.format(String, Object...)
  String formattedMessage = String.format(conversionPattern, event.getDateTime(), event.getLevel(), event.getLogger(), event.getThreadName(), event.getMessage());

  // 5. Return the formatted message
  return formattedMessage;
}

public String format(LoggingEvent event){
    String message = event.getMessage();
    String result = "";
    // Use a regex to extract the conversion pattern from the message
    Pattern pattern = Pattern.compile("%(.*?)%");
    Matcher matcher = pattern.matcher(message);

    // Iterate over each match and extract the conversion specifier
    while (matcher.find()) {
        String converter = matcher.group(0);
        // Check if the conversion specifier is valid
        if (converter.equalsIgnoreCase("%d")) {
            result += String.valueOf(event.getDateTime());
        } else if (converter.equalsIgnoreCase("%p")) {
            result += event.getLevel();
        } else if (converter.equalsIgnoreCase("%m")) {
            result += event.getMessage();
        } else {
            result += matcher.group(0);
        }
    }

    return result;
}

