private int parseEndOfLine(String headerPart, int end) {
    int endOfLineIndex = end;
    while (endOfLineIndex < headerPart.length() && headerPart.charAt(endOfLineIndex) != '\r') {
        endOfLineIndex++;
    }
    if (endOfLineIndex < headerPart.length() && headerPart.charAt(endOfLineIndex) == '\r') {
        endOfLineIndex++;
    }
    if (endOfLineIndex < headerPart.length() && headerPart.charAt(endOfLineIndex) == '\n') {
        endOfLineIndex++;
    }
    return endOfLineIndex;
}

private int parseEndOfLine(String headerPart, int end) {
	int indexOfCR = headerPart.indexOf("\r", end);
	int indexOfLF = headerPart.indexOf("\n", end);

	if (indexOfCR == -1) {
		if (indexOfLF == -1) {
			throw new IllegalStateException("End of line not found");
		}

		return indexOfLF;
	}

	if (indexOfLF == -1) {
		return indexOfCR;
	}

	return Math.min(indexOfCR, indexOfLF);
}

private int parseEndOfLine(String headerPart, int end) {
    for (int i = end; i < headerPart.length(); i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            return i;
        }
    }
    throw new IllegalArgumentException("Invalid header part");
}

private int parseEndOfLine(String headerPart, int end) {
  int currentIndex = end;

  while (currentIndex < headerPart.length() && !headerPart.substring(currentIndex, currentIndex + 2).equals("\r\n")) {
    currentIndex++;
  }

  if (currentIndex == headerPart.length()) {
    throw new RuntimeException("Invalid HTTP header");
  }

  return currentIndex;
}

