public void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File is null");
    }

    if (file.isDirectory()) {
        File[] files = file.listFiles();
        for (File childFile : files) {
            forceDeleteOnExit(childFile);
        }
    }

    file.delete();
}

