        // Step 1: Create a list of all the sources
        List<V> sources = new ArrayList<>();
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            sources.add(entry.getValue());
        }

        // Step 2: Create a list of all the targets
        List<V> targets = new ArrayList<>();
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            targets.add(entry.getValue());
        }

        // Step 3: Create a bipartite graph with the sources and targets
        Graph<V,E> bipartiteGraph = new Graph<>(target.getGraphType(), sources, targets);

        // Step 4: Add edges to the graph
        for (Map.Entry<String, V> entry : resultMap.entrySet()) {
            String key = entry.getKey();
            V source = entry.getValue();
            V target = entry.getValue();
            E edge = target.addEdge(source, key);
            if (edge != null) {
                bipartiteGraph.addEdge(edge);
            }
        }

        // Step 5: Add the bipartite graph to the target graph
        target.addGraph(bipartiteGraph);
    }

