    if (pos < 0 || pos >= buffer.length) {
        throw new IndexOutOfBoundsException("Position is outside the bounds of the buffer");
    }

    // Iterate through the buffer from the specified position
    for (int i = pos; i < buffer.length; i++) {
        // If the current byte matches the value, return the position
        if (buffer[i] == value) {
            return i;
        }
    }

    // If the value was not found, return -1
    return -1;
}

