public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Calculate the size of the message
    int size = schema.getSerializedSize(message);

    // Calculate the size of the length field
    int sizeSize = BufferedOutputUtils.computeFieldSize(size);

    // Write the length field to the output stream
    BufferedOutputUtils.writeUInt32NoTag(size, out);

    // Write the message to the output stream
    schema.writeDelimitedTo(out, message);

    return size + sizeSize;
}

private static int writeDelimitedTo(OutputStream out, Object message, Schema<?> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("Output stream should not be null.");
    }
    if (message == null) {
        throw new NullPointerException("Message should not be null.");
    }
    if (schema == null) {
        throw new NullPointerException("Schema should not be null.");
    }
    if (buffer == null) {
        throw new NullPointerException("Buffer should not be null.");
    }

    // Serialize the message
    int length = serializer.serializer(message, schema, buffer);

    // Prefix the length of the message
    try {
        byte[] lengthBytes = ByteBuffer.allocate(4).putInt(length).array();
        out.write(lengthBytes);
    } catch (IOException e) {
        throw new IOException("Error writing message length to output stream", e);
    }

    // Write the serialized message to the output stream
    try {
        out.write(buffer.toByteArray());
    } catch (IOException e) {
        throw new IOException("Error writing serialized message to output stream", e);
    }

    // Return the size of the message
    return length;
}

def write_delimited_to(out: OutputStream, message: T, schema: Schema[T], buffer: LinkedBuffer): Int = {
    // Write the message length to the output stream
    val length = message.toByteArray(schema, buffer).limit()
    out.writeInt(length)

    // Write the message to the output stream
    out.write(message.toByteArray(schema, buffer))

    // Return the length of the message
    length
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new IOException("OutputStream cannot be null");
    }

    if (message == null) {
        throw new IOException("Message cannot be null");
    }

    if (schema == null) {
        throw new IOException("Schema cannot be null");
    }

    if (buffer == null) {
        throw new IOException("LinkedBuffer cannot be null");
    }

    int messageSize = schema.getSize(message);

    // Write the message size to the output stream
    out.write((messageSize >> 24) & 0x000000FF);
    out.write((messageSize >> 16) & 0x000000FF);
    out.write((messageSize >> 8) & 0x000000FF);
    out.write(messageSize & 0x000000FF);

    // Write the message to the output stream
    byte[] bytes = buffer.writeAndGetBytes(message, schema);

    // Ensure that the message fits in the output stream
    if (bytes.length > Integer.MAX_VALUE) {
        throw new IOException("Message too large");
    }

    // Write the message bytes to the output stream
    out.write(bytes);

    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema) {
    int size = 0;
    try {
        T output = schema.writeObject(message);
        size = output.length;
        T input = new T(size);
        output.readBytes(input);
        out.write(input.array(), 0, size);

    catch (IOException e) {
        e.printStackTrace();
    }
    return size;
}

