}

private static Class<?>[] resolveArguments(Type[] actualTypeArguments, Class<?> targetType) {
    Class<?>[] resolvedClasses = new Class<?>[actualTypeArguments.length];
    for (int i = 0; i < actualTypeArguments.length; i++) {
        resolvedClasses[i] = resolveArgument(actualTypeArguments[i], targetType);
    }
    return resolvedClasses;
}

private static Class<?> resolveArgument(Type actualTypeArgument, Class<?> targetType) {
    if (actualTypeArgument instanceof Class) {
        return (Class<?>) actualTypeArgument;
    } else if (actualTypeArgument instanceof TypeVariable) {
        return resolveTypeVariable((TypeVariable<?>) actualTypeArgument, targetType);
    } else if (actualTypeArgument instanceof WildcardType) {
        return resolveWildcard((WildcardType) actualTypeArgument, targetType);
    } else {
        return null;
    }
}

private static Class<?> resolveTypeVariable(TypeVariable<?> typeVariable, Class<?> targetType) {
    Type[] bounds = typeVariable.getBounds();
    for (Type bound : bounds) {
        if (bound instanceof Class) {
            return (Class<?>) bound;
        }
    }
    return null;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }
    ParameterizedType pt = (ParameterizedType) genericType;
    T[] resolvedArguments = pt.getActualTypeArguments();
    if (resolvedArguments == null || resolvedArguments.length != targetType.getTypeParameters().length) {
        return null;
    }
    Class<?>[] argumentClasses = Arrays.stream(resolvedArguments)
            .map(arg -> (Class<?>) arg)
            .toArray(Class[]::new);
    return argumentClasses;
}

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // If the given type is not parameterized, return null
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Get the parameter count for the given type
    int parameterCount = ((ParameterizedType) genericType).getActualTypeArguments().length;

    // If the parameter count is not equal to the type arguments for the target type, return null
    if (parameterCount != targetType.getTypeParameters().length) {
        return null;
    }

    // Create an array to store the resolved type arguments
    Class<?>[] resolvedArguments = new Class[parameterCount];

    // Get the type arguments for the given generic type
    Type[] typeArguments = ((ParameterizedType) genericType).getActualTypeArguments();

    // For each type argument, if the type argument implements all the bounds of the corresponding target type,
    // add it to the resolvedArguments array. Otherwise, return null.
    for (int i = 0; i < parameterCount; i++) {
        Type typeArgument = typeArguments[i];
        TypeVariable<?> var = targetType.getTypeParameters()[i];

        if (!((Class<?>) typeArgument).isAssignableFrom((Class<?>) var.getBounds()[0])) {
            return null;
        }

        resolvedArguments[i] = (Class<?>) typeArgument;
    }

    return resolvedArguments;
}

Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    if (genericType != null) {
      if (genericType instanceof ParameterizedType) {
        ParameterizedType paramType = (ParameterizedType) genericType;
        Type[] typeArgs = paramType.getActualTypeArguments();
        Class<?>[] classArgs = new Class<?>[typeArgs.length];
        for (int i = 0; i < typeArgs.length; i++) {
          Type typeArg = typeArgs[i];
          if (typeArg instanceof Class) {
            classArgs[i] = (Class<?>) typeArg;
          } else if (typeArg instanceof TypeVariable) {
            TypeVariable<?> typeVar = (TypeVariable<?>) typeArg;
            Type bounds[] = typeVar.getBounds();
            if (bounds.length == 1 && bounds[0] instanceof Class) {
              classArgs[i] = (Class<?>) bounds[0];
            }
          }
        }
        if (Arrays.stream(classArgs).noneMatch(Objects::isNull)) {
          return classArgs;
        }
      }
    }
    return null;
  }

public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
    // Check if the generic type is parameterized
    if (!(genericType instanceof ParameterizedType)) {
        return null;
    }

    // Check if the target type is a subclass of the raw type represented by the generic type
    if (!targetType.getClass().isAssignableFrom(genericType.getRawType().getClass())) {
        return null;
    }

    return ((ParameterizedType) genericType).getActualTypeArguments();
}

