public long readLong(final int offset) {
        try {
            // Start at the provided offset
            int index = offset;
            // Read the first byte to determine the sign
            int firstByte = this.readByte(index++);
            // Read the 4 bytes that make up the long value
            int value = (firstByte << 56) | (this.readByte(index++) & 0xFF) << 48 | (this.readByte(index++) & 0xFF) << 40 | (this.readByte(index++) & 0xFF) << 32 | (this.readByte(index++) & 0xFF) << 24 | (this.readByte(index++) & 0xFF) << 16 | (this.readByte(index++) & 0xFF) << 8 | (this.readByte(index++) & 0xFF);
            // Negate the value if the sign is negative
            if (firstByte >= 128) {
                value = value - (1 << 63);
            }
            return value;
        } catch (IndexOutOfBoundsException e) {
            throw new ClassFormatException("Invalid long value in class file");
        }
    }

private long readLong(final int offset) throws IOException {
