    if (offset < 0) {
        throw new IllegalArgumentException("Offset must be non-negative.");
    }
    // Initialize and adjust offset
    long value = 0;
    offset = adjustOffset(offset);
    // Read and return value
    for (int i = 0; i < Long.BYTES; i++) {
        value |= (this.buffer[offset + i] & 0xFFL) << (8 * (Long.BYTES - i - 1));
    }
    return value;
}

public long readLong(int offset) {
        if (offset < 0 || offset > this.byteArray.length - 8) {
            throw new IllegalArgumentException("Offset out of bounds");
        }
        byte[] bytes = byteArray.clone();
        long result = 0;
        result |= (bytes[offset] & 0xff) << 0;
        result |= (bytes[offset+1] & 0xff) << 8;
        result |= (bytes[offset+2] & 0xff) << 16;
        result |= (bytes[offset+3] & 0xff) << 24;
        result |= (bytes[offset+4] & 0xff) << 32;
        result |= (bytes[offset+5] & 0xff) << 40;
        result |= (bytes[offset+6] & 0xff) << 48;
        result |= (bytes[offset+7] & 0xff) << 56;
        return result;
    }

