    // Ensure the provided offset is valid
    if (offset < 0 || offset > this.data.length - 1) {
        throw new IllegalArgumentException("The provided offset is invalid.");
    }

    // Read the value from the specified offset and ensure it fits in the range of a signed long
    long value = ByteBuffer.wrap(Arrays.copyOfRange(this.data, offset, offset + 8)).getLong();
    if (value < Long.MIN_VALUE || value > Long.MAX_VALUE) {
        throw new IllegalArgumentException("The value read from the specified offset is invalid.");
    }

    // Return the read value
    return value;
}

public long readLong(final int offset) {
    // Read the low-order 4 bytes of the long value first
    final int low = readInt(offset);

    // Read the high-order 4 bytes of the long value
    final int high = readInt(offset + 4);

    // Combine the low-order and high-order bytes to form the long value
    return ((long)high << 32) | (low & 0xFFFFFFFFL);
}

public int readInt(final int offset) {
    // Read the 4 bytes of the int value at the specified offset
    byte[] buffer = new byte[4];
    this.read(buffer, offset, 4);

    // Convert the bytes to an int value
    return ByteBuffer.wrap(buffer).getInt();
