public void send(final String message, final Consumer<String> onSuccess, final Consumer<Exception> onError) {
    // Create a new thread to send the message
    Thread thread = new Thread(() -> {
        try {
            // Send the message to each of the clients
            for (TelnetClient client : clients) {
                client.send(message);
            }
            // If there was no error, call the onSuccess callback
            onSuccess.accept(message);
        } catch (Exception e) {
            // If there was an error, call the onError callback
            onError.accept(e);
        }
    });
    // Start the thread
    thread.start();
}

