protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long startTime = start;
    long endTime = start;

    while (endTime + FETCH_DATA_DURATION < end) {
      endTime += FETCH_DATA_DURATION;
      timeRanges.add(new TimeRange(startTime, endTime));
      startTime = endTime;
    }

    if (startTime < end) {
      timeRanges.add(new TimeRange(startTime, end));
    }

    return timeRanges;
  }

public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    if (end - start < FETCH_DATA_DURATION) {
        if (start >= FETCH_DATA_DURATION && end < FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, end));
        } else if (start < FETCH_DATA_DURATION && end >= FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, FETCH_DATA_DURATION - 1));
        }
    } else {
        long divider = (end - start) / FETCH_DATA_DURATION;
        long startPos = start;
        for (int i = 0; i <= divider; i++) {
            long endPos = startPos + FETCH_DATA_DURATION - 1;
            if (endPos > end) {
                endPos = end;
            }
            timeRanges.add(new TimeRange(startPos, endPos));
            startPos = endPos + 1;
        }
    }

    return timeRanges;
}

private List<TimeRange> buildTimeRanges(long start, long end) {
    if (start >= FETCH_DATA_DURATION || end >= FETCH_DATA_DURATION) {
        throw new IllegalArgumentException("Time range should be less than " + FETCH_DATA_DURATION);
    }
    List<TimeRange> timeRanges = new ArrayList<>();
    while (start < end) {
        long currentEnd = start + FETCH_DATA_DURATION;
        if (currentEnd > end) {
            currentEnd = end;
        }
        timeRanges.add(new TimeRange(start, currentEnd));
        start = currentEnd;
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new LinkedList<TimeRange>();
    long currentStart = start;
    long currentEnd = end;
    while (currentEnd - currentStart >= FETCH_DATA_DURATION) {
        if (currentStart + FETCH_DATA_DURATION <= currentEnd) {
            timeRanges.add(new TimeRange(currentStart, currentStart + FETCH_DATA_DURATION));
            currentStart += FETCH_DATA_DURATION;
        } else {
            timeRanges.add(new TimeRange(currentStart, currentEnd));
            break;
        }
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    long duration = FETCH_DATA_DURATION;
    long startBoundary = start - duration;
    long endBoundary = end + duration;
    long currentStart = start;
    long currentEnd = end;
    List<TimeRange> ranges = new ArrayList<>();

    while (currentStart < endBoundary && currentEnd > startBoundary) {
        ranges.add(new TimeRange(currentStart, currentEnd));
        currentStart = currentEnd + 1;
        currentEnd = Math.min(currentEnd + duration, endBoundary);
    }

    return ranges;
}

