static long compressTimeBucket(long timeBucket, int dayStep) {
    // Step 1: Validate input parameters
    if (timeBucket < 10000000 || timeBucket > 99999999) {
        throw new IllegalArgumentException("Invalid time bucket: " + timeBucket);
    }
    if (dayStep <= 0 || dayStep > 31) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }

    // Step 2: Extract year, month, and day from the time bucket
    long year = timeBucket / 1000000;
    long month = (timeBucket % 1000000) / 10000;
    long day = timeBucket % 10000;

    // Step 3: Calculate the new day based on the day step
    long newDay = day - dayStep + 1;

    // Step 4: Validate new day range
    if (newDay < 1 || newDay > 31) {
        throw new IllegalArgumentException("Invalid day step: " + dayStep);
    }

    // Step 5: Update the time bucket
    timeBucket %= 1000000;
    timeBucket /= 10000;
    timeBucket *= 10000;
    timeBucket += newDay;

    return timeBucket;
}

public static long compressTimeBucket(long timeBucket, int dayStep) {

// Get the day of month from the time bucket
int dayOfMonth = (int) (timeBucket % 100);

// Get the month from the time bucket
int month = (int) (timeBucket / 100);

// Get the year from the time bucket
int year = (int) (timeBucket / 10000);

// Re-format the day of month based on the day step
int newDayOfMonth = dayOfMonth - dayStep;
if (newDayOfMonth <= 0) {
newDayOfMonth = 1;
}

// Construct the new time bucket value
long newTimeBucket = (year * 10000) + (month * 100) + newDayOfMonth;

return newTimeBucket;
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    long newTimeBucket = timeBucket;
    int year = (int) (timeBucket / 1e4);
    int month = (int) ((timeBucket % 1e4) / 1e2);
    int day = (int) ((timeBucket % 1e4) % 1e2);
    if (dayStep < 0) {
        throw new IllegalArgumentException("Invalid compression ratio, must be positive");
    }
    if (dayStep == 0) {
        return timeBucket;
    }
    day += dayStep;
    while (day > 31) {
        month++;
        if (month > 12) {
            year++;
            month = 1;
        }
        day -= 31;
    }
    newTimeBucket = year * 1e4 + month * 1e2 + day;
    return newTimeBucket;
}

static long compressTimeBucket(long timeBucket,int dayStep){
	if(timeBucket <0 || dayStep<=0){
		throw new IllegalArgumentException("Invalid input for compressTimeBucket");
	}
	long[] days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31};
	long year = (timeBucket / 100) % 100;
	long month = ((timeBucket % 10000) / 100) % 12;
	long day = timeBucket % 100;

	if(dayStep + day > days[month-1]){
		day = 1;
		month = month + 1;
		if(month == 13){
			year = year + 1;
			month = 1;
		}
	}else{
		day = day + dayStep
	}

	long compressedTimeBucket = year*10000 + month*100 + day;
	return compressedTimeBucket;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Compute the size of the UTF-8 string beginning at the specified index and with the specified length
    int utf8Size = 0;

    for (int i = index; i < index + len; i++) {
        int codePoint = str.charAt(i);

        if (codePoint <= 0x007F) {
            utf8Size++;
        } else if (codePoint <= 0x07FF) {
            utf8Size += 2;
        } else if (codePoint <= 0xFFFF) {
            utf8Size += 3;
        } else if (codePoint <= 0x10FFFF) {
            utf8Size += 4;
        }
    }

    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    // Validate input
    if (str == null) {
      throw new IllegalArgumentException("str cannot be null");
    }
    if (index < 0 || index >= str.length()) {
      throw new IndexOutOfBoundsException("index is not within the bounds of the string");
    }
    if (len < 0 || len > str.length() - index) {
      throw new IllegalArgumentException("len is not a valid length");
    }

    // Initialize variables
    int utf8Len = 0;
    for (int i = index; i < index + len && i < str.length(); i++) {
      utf8Len += str.charAt(i) < 0x80 ? 1 : 2;
    }

    // Return the utf8 length
    return utf8Len;
  }

public static int computeUTF8Size(final CharSequence str,final int index,final int len){
        // treat null/invalid input as empty string
        if(str == null || index < 0 || len < 0 || index + len > str.length()){
            return 0;
        }

        // compute size of each character in the string
        int size = 0;
        for(int i = index; i < index + len; i++){
            final char c = str.charAt(i);
            if(c <= 0x7F){
                size++;
            } else if(c <= 0x7FF){
                size += 2;
            } else if(Character.isHighSurrogate(c)){
                final char low = str.charAt(++i);
                if(Character.isLowSurrogate(low)){
                    size += 4;
                } else {
                    // error: unpaired surrogate
                    throw new IllegalArgumentException("Invalid surrogate character at position " + i + " in string: " + str);
                }
            } else {
                size += 3;
            }
        }

        return size;
    }

public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    for (int i = index; i < index + len; i++) {
        size += str.charAt(i) >= 0x10000 ? 4 : str.charAt(i) >= 0x800 ? 3 : str.charAt(i) >= 0x80 ? 2 : 1;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    final LinkedList<Integer> utf8Bytes = new LinkedList<>();
    final int strLen = str.length();

    final int startIndex = Math.min(Math.max(index, 0), strLen - len);
    final int endIndex = Math.min(Math.max(index + len, 0), strLen);

    for (int i = startIndex; i < endIndex; i++) {
        char c = str.charAt(i);
        if (c >= '\u0080') {
            utf8Bytes.add(c);
        }
    }

    return utf8Bytes.size();
}

