	if (str == null) {
		return null;
	}

	int len = str.length();
	if (len == 0) {
		return "";
	}

	char[] chars = str.toCharArray();
	char[] result = new char[chars.length];

	for (int i = 0, j = result.length - 1; i < len; i++, j--) {
		result[j] = chars[i];
	}

	return new String(result);
