public static String sub(String str,int start,int end) {
    // Check if the input string is null or empty
    if (str == null || str.isEmpty()) {
        throw new IllegalArgumentException("The input string cannot be null or empty");
    }

    // Check if the start index is valid
    if (start < 0 || start >= str.length()) {
        throw new IndexOutOfBoundsException("The start index cannot be negative or greater than the length of the input string");
    }

    // Check if the end index is valid
    if (end < 0 || end > str.length()) {
        throw new IndexOutOfBoundsException("The end index cannot be negative or greater than the length of the input string");
    }

    // Check if the start index is less than the end index
    if (start > end) {
        throw new IllegalArgumentException("The start index cannot be greater than the end index");
    }

    // Return the substring
    return str.substring(start, end);
}

