public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Validate input parameters
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("str, session, and lb cannot be null");
    }

    // Write each character from the string into the LinkedBuffer
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);
        if (c > 0x00 && c <= 0x7F) {
            lb.append((byte) c);
        } else if (c > 0x07F && c <= 0x7FF) {
            lb.append((byte) (0xC0 | (c >> 6)));
            lb.append((byte) (0x80 | (c & 0x3F)));
        } else if (c > 0x7FF && c <= 0xFFFF) {
            lb.append((byte) (0xE0 | (c >> 12)));
            lb.append((byte) (0x80 | (c >> 6) & 0x3F));
            lb.append((byte) (0x80 | c & 0x3F));
        } else if (c > 0xFFFF && c <= 0x10FFFF) {
            lb.append((byte) (0xF0 | (c >> 18)));
            lb.append((byte) (0x80 | (c >> 12) & 0x3F));
            lb.append((byte) (0x80 | (c >> 6) & 0x3F));
            lb.append((byte) (0x80 | c & 0x3F));
        } else {
            throw new IllegalArgumentException("Invalid character: " + c);
        }
    }

    return lb;
}

public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    // Convert String to UTF-8 bytes
    ByteBuffer bytes = StandardCharsets.UTF_8.encode(str);

    // Write bytes to LinkedBuffer
    lb.write(bytes);

    // Return LinkedBuffer
    return lb;
}

public static LinkedBuffer writeUTF8(CharSequence str, WriteSession session, LinkedBuffer lb) {
    if (str == null || session == null || lb == null) {
        throw new IllegalArgumentException("Input arguments cannot be null");
    }

    // Write the utf8-encoded bytes into the LinkedBuffer
    byte[] bytes = str.toString().getBytes("UTF-8");
    lb.writeBytes(bytes);

    // Truncate the LinkedBuffer to the correct length
    lb.truncate(bytes.length);

    // Return the updated LinkedBuffer
    return lb;
}

