public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("Key not found: " + key);
    }
    value = value.replaceAll("\\$\\{(\\w+)\\}", (m) -> {
        String varName = m.group(1);
        return props.getProperty(varName, m.group());
    });
    return value;
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    if (value == null) {
        throw new IllegalArgumentException("No value found for key: " + key);
    }
    return value.replaceAll("\\$[a-zA-Z0-9]+", match -> {
        String variable = match.substring(1);
        String replacement = props.getProperty(variable);
        if (replacement == null) {
            throw new IllegalArgumentException("No value found for variable: " + variable);
        }
        return replacement;
    });
}

public static String findAndSubst(String key, Properties props) {
    String value = props.getProperty(key);
    value = variableSubstitution(value, props);
    return value;
}

public static String findAndSubst(String key,Properties props) {
	// 1. Find the value corresponding to key in props
	String value = props.getProperty(key);

	// 2. Perform variable substitution on the found value
	value = value.replaceAll("\\$\\{([^}]+)}", match -> {
		String varName = match.group(1);
		return props.getProperty(varName);
	});

	return value;
}

