public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
	List<PathSegmentImpl> pathSegments = new ArrayList<>();
	if (u.isAbsolute()) {
		// Ignore the leading '/'
		String pathString = u.getPath().substring(1);
		// Split the path string into segments based on '/' delimiter
		String[] pathSegmentsArray = pathString.split("/");
		for (String pathSegmentString : pathSegmentsArray) {
			pathSegments.add(new PathSegmentImpl(pathSegmentString, decode));
		}
	} else {
		// The path component is a relative path component
		// Split the path string into segments based on '/' delimiter
		String[] pathSegmentsArray = u.getPath().split("/");
		for (String pathSegmentString : pathSegmentsArray) {
			pathSegments.add(new PathSegmentImpl(pathSegmentString, decode));
		}
	}
	return pathSegments;
}

public List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Validate input
    if (u == null) {
        throw new IllegalArgumentException("URI cannot be null");
    }

    // Initialize variables
    String path = u.getPath();
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Decode path
    if (path != null && decode) {
        path = URLDecoder.decode(path, StandardCharsets.UTF_8);
    }

    // Split path into segments
    if (path != null) {
        String[] segments = path.split("/");
        for (String segment : segments) {
            if (segment.isEmpty()) {
                continue;
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    // Return path segments
    return pathSegments;
}

public static List<String> decodePath(URI u, boolean decode) {
    List<String> pathSegments = new ArrayList<>();
    if (u != null && u.getPath() != null) {
        String[] segments = u.getPath().split("/");
        for (String segment : segments) {
            if (!segment.isEmpty()) {
                pathSegments.add(decode ? decode(segment) : segment);
            }
        }
    }
    return pathSegments;
}

private static String decode(String segment) {
    String decodedSegment = new String(segment.getBytes(StandardCharsets.UTF_8), StandardCharsets.UTF_8);
    return decodedSegment.replace("+", "%20");
}

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    // Create an empty list to store the path segments
    List<PathSegmentImpl> pathSegments = new ArrayList<>();

    // Get the path component of the URI
    String path = u.getPath();

    // If the path is not null or empty
    if (path != null && !path.isEmpty()) {
      // If the path is an absolute path component, ignore the leading '/'
      if (path.startsWith("/")) {
        path = path.substring(1);
      }

      // Split the path into individual segments based on the '/' delimiter
      String[] segments = path.split("/");

      // Iterate over the segments
      for (int i = 0; i < segments.length; i++) {
        // If the path segment is not empty, add it to the list
        if (!segments[i].isEmpty()) {
          pathSegments.add(new PathSegmentImpl(segments[i], decode));
        }
      }
    }

    // Return the list of path segments
    return pathSegments;
  }

public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    String path = u.getRawPath();
    if (path == null) {
      throw new IllegalArgumentException("Input URI does not have a path component");
    }

    String[] pathSegments = path.split("/");

    if (decode) {
      for (int i = 0; i < pathSegments.length; i++) {
        pathSegments[i] = java.net.URLDecoder.decode(pathSegments[i], "UTF-8");
      }
    }

    List<PathSegmentImpl> segments = new ArrayList<>();
    for (int i = 0; i < pathSegments.length; i++) {
      segments.add(new PathSegmentImpl(pathSegments[i]));
    }

    return segments;
  }

