private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    String[] descriptorParts = descriptor.split(";");
    for (String part : descriptorParts) {
        if (part.startsWith("(")) {
            // method descriptor, pop its arguments
            part = part.substring(1, part.length() - 1);
            while ((part.length() > 0) && part.startsWith("L")) {
                // object type, pop its entire descriptor
                int semicolonIdx = part.indexOf(";");
                if (semicolonIdx == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: " + part);
                }
                part = part.substring(semicolonIdx + 1);
            }
            int argumentCount = Integer.parseInt(part);
            for (int i = 0; i < argumentCount; i++) {
                // pop one argument's descriptor
                Stack<String> descriptorStack = getOutputStack();
                if (descriptorStack.isEmpty()) {
                    throw new IllegalStateException("Output stack is empty");
                }
                descriptorStack.pop();
            }
        } else {
            // primitive type, pop its size from the stack
            int primitiveSize = getPrimitiveSize(part);
            Stack<Integer> sizeStack = getOutputStack();
            if (sizeStack.isEmpty()) {
                throw new IllegalStateException("Output stack is empty");
            }
            int actualSize = sizeStack.pop();
            if (actualSize != primitiveSize) {
                throw new IllegalStateException("Actual size " + actualSize + " does not match expected size " + primitiveSize + " for primitive type " + part);
            }
        }
    }
}

