public static int writeTo(DataOutput out, LinkedBuffer node) throws IOException {
	// Check if the DataOutput is null
	if (out == null) {
		throw new IllegalArgumentException("DataOutput cannot be null");
	}
	// Check if the LinkedBuffer is null
	if (node == null) {
		throw new IllegalArgumentException("LinkedBuffer cannot be null");
	}

	// Initialize the total content size variable
	int contentSize = 0;

	// While the LinkedBuffer has next node
	while (node != null) {
		// Check if the current node is null
		if (node == null) {
			throw new IllegalArgumentException("Current LinkedBuffer node is null");
		}
		// Get the current node's data
		byte[] data = node.getData();
		// Check if the current node's data is null
		if (data == null) {
			throw new IllegalArgumentException("Current LinkedBuffer node data is null");
		}
		// Write the current node's data to the DataOutput
		out.writeBytes(data, 0, data.length);
		// Increment the total content size
		contentSize += data.length;
		// Move to the next node
		node = node.getNext();
	}

	// Return the total content size
	return contentSize;
}

