public int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 0) {
        throw new IllegalArgumentException("desiredCapacity cannot be negative");
    }

    int potentialPrime = nextOddNumber(desiredCapacity);

    while (!isPrime(potentialPrime)) {
        potentialPrime += 2;
    }

    return potentialPrime;
}

private static int nextOddNumber(int num) {
    if (num % 2 == 0) {
        return num + 1;
    } else {
        return num;
    }
}

private static boolean isPrime(int num) {
    if (num <= 1) {
        return false;
    } else if (num == 2) {
        return true;
    } else if (num % 2 == 0) {
        return false;
    } else {
        for (int i = 3; i * i <= num; i += 2) {
            if (num % i == 0) {
                return false;
            }
        }
        return true;
    }
}

