public static int nextPrime(int desiredCapacity) {
  // Check if the input is valid
  if (desiredCapacity < 0) {
    throw new IllegalArgumentException("Desired capacity cannot be negative");
  }

  // Find the next prime number using the Sieve of Eratosthenes algorithm
  boolean[] primeNumbers = new boolean[desiredCapacity];
  for (int i = 2; i * i <= desiredCapacity; i++) {
    if (!primeNumbers[i]) {
      for (int j = i * i; j <= desiredCapacity; j += i) {
        primeNumbers[j] = true;
      }
    }
  }

  // Find the first prime number greater than or equal to the desired capacity
  for (int i = desiredCapacity; i < primeNumbers.length; i++) {
    if (!primeNumbers[i]) {
      return i;
    }
  }

  throw new ArithmeticException("No prime number found greater than or equal to " + desiredCapacity);
}

