private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();

    // put all the key-value pairs from the JsonObject into the content map
    for (Entry<String, Object> entry : jsonObject.entrySet()) {
        content.put(entry.getKey(), entry.getValue());
    }

    // if there are any @ signs in the jsonObject, parse them out and put them into the content map
    if (jsonObject.containsKey("@") && jsonObject.get("@") instanceof JsonObject) {
        JsonObject ats = (JsonObject) jsonObject.get("@");
        for (Entry<String, Object> entry : ats.entrySet()) {
            content.put("@" + entry.getKey(), entry.getValue());
        }
    }

    return content;
}

