private List<Map<String, Object>> buildAts(JsonObject jsonObject) {
  List<Map<String, Object>> ats = new ArrayList<>();

  // For each "at" in the "ats" array, build a new Map and add it to the list
  for (JsonObject at : jsonObject.getJsonArray("ats")) {
    Map<String, Object> atMap = new HashMap<>();

    // For each field in the "at" object, add it to the Map
    for (String field : at.getFieldNames()) {
      atMap.put(field, at.getValue(field));
    }

    ats.add(atMap);
  }

  // Return the list of "at" Maps
  return ats;
}

