public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }

    int length = str.length();
    if (length == 0) {
        return "";
    }

    StringBuilder builder = new StringBuilder(length);
    int index = 0;
    while (index < length) {
        char c = str.charAt(index);
        if (c == '\\') {
            if (index == length - 1) {
                throw new IllegalArgumentException("Illegal escape character at the end of the string");
            }
            char nextChar = str.charAt(index + 1);
            switch (nextChar) {
                case '"':
                    builder.append('"');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                case 'b':
                    builder.append('\b');
                    break;
                case 'f':
                    builder.append('\f');
                    break;
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case 'u':
                    if (index + 5 > length) {
                        throw new IllegalArgumentException("Illegal unicode escape character in the middle of the string");
                    }
                    String hexChars = str.substring(index + 2, index + 6);
                    int codePoint = Integer.parseInt(hexChars, 16);
                    builder.append((char) codePoint);
                    break;
                default:
                    throw new IllegalArgumentException("Illegal escape character: \\" + nextChar);
            }
            index += 2;
        } else {
            builder.append(c);
            index++;
        }
    }

    return builder.toString();
}

