                }
                backslashCount = 0;
            }
            sb.append(c);
        }
        return sb.toString();
    }

private static char handleEscapedChar(char c) {
        switch (c) {
            case 'b':
                return '\b';
            case 't':
                return '\t';
            case 'n':
                return '\n';
            case 'f':
                return '\f';
            case 'r':
                return '\r';
            case '"':
                return '"';
            case '\'':
                return '\'';
            case '\\':
                return '\\';
            default:
                throw new IllegalArgumentException("Invalid escaped character: \\" + c);
        }
    }

