    return result;
}

private static Object copyArrayGrow1(final Object array, final Class<?> newArrayComponentType) {
    if (array == null && newArrayComponentType == null) {
        throw new IllegalArgumentException("Array and new array component type cannot both be null");
    }

    int newLength = Array.getLength(array) + 1;
    Object newArray = Array.newInstance(newArrayComponentType != null ? newArrayComponentType : array.getClass().getComponentType(), newLength);

    // Copy the original array into the new array
    System.arraycopy(array, 0, newArray, 0, Array.getLength(array));

    return newArray;
}

private static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        // If array is null, create a new array of size 1 and return it
        return Array.newInstance(newArrayComponentType, 1);
    }

    // If array is non-null, create a new array of size 1 greater than the input and copy the input values to it
    int length = Array.getLength(array);
    Object newArray = Array.newInstance(array.getClass().getComponentType(), length + 1);
    System.arraycopy(array, 0, newArray, 0, length);
    return newArray;
}

private static Object copyArrayGrow1(Object array, Class<?> newArrayComponentType) {
    if (array == null) {
        array = Array.newInstance(newArrayComponentType, 1);
    } else {
        int length = Array.getLength(array);
        Object newArray = Array.newInstance(Array.getComponentType(array), length + 1);
        System.arraycopy(array, 0, newArray, 0, length);
        array = newArray;
    }
    return array;
}

private int computeBinaryLog(int n) {
    int binaryLog = 0;
    while (n > 1) {
        binaryLog++;
        n >>= 1;
    }
    return binaryLog + 1;
}

private int computeBinaryLog(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be positive");
    } else if (n >= MAX_INT) {
        throw new IllegalArgumentException("n must be less than MAX_INT");
    }
    for (int i = 0; i < n; i++) {
        if (n >= (1 << i)) {
            n -= (1 << i);
        } else {
            return i;
        }
    }
    return n;
}

int computeBinaryLog(int n) {

    // Initialize the value of the binary log to 0
    int binaryLog = 0;

    // Loop while the current power of 2 is less than the input n
    while (Math.pow(2, binaryLog) < n) {
      // Increment the binary log
      binaryLog++;
    }

    // Return the binary log plus 1
    return binaryLog + 1;
  }

private int computeBinaryLog(int n) {
    if (n <= 1) {
        return 0;
    }
    int result = 1;
    while (n > 1) {
        n >>= 1;
        result++;
    }
    return result;
}

