protected int removeUnusedNodes() {
    // Iterate through the category tree and remove nodes that have no active children
    int numRemovedNodes = 0;
    for (Node currentNode : this.categoryTree) {
        if (!currentNode.hasActiveChildren()) {
            this.categoryTree.remove(currentNode);
            numRemovedNodes++;
        }
    }
    return numRemovedNodes;
}

protected int removeUnusedNodes() {
    // Check if the root category is inactive
    if (root == null || root.isInactive()) {
        throw new IllegalStateException("No root category available");
    }

    // Create a set to store all the nodes in the tree
    Set<Category> allNodes = new HashSet<>();
    queue.add(root);

    // Traverse the tree and add all nodes to the set
    while (!queue.isEmpty()) {
        Category current = queue.poll();
        allNodes.add(current);
        queue.addAll(current.getSubcategories());
    }

    // Remove any inactive nodes from the set
    allNodes.removeIf(Category::isInactive);

    // Return the number of remaining nodes
    return allNodes.size();
}

private int removeUnusedNodes() {
    int nodesRemoved = 0;
    // Iterate through all nodes in the Category tree
    for (Node node : traversal(this)) {
      // Check if the node is inactive
      if (!node.isActive()) {
        // Remove the node from the tree
        node.removeFromParent();
        // Increment the number of nodes removed
        nodesRemoved++;
      }
    }
    return nodesRemoved;
  }

