public static String readUtf8(int constantPoolEntryIndex, char[] charBuffer) {
    // Check if the input is valid
    if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= Constants.MAX_CONSTANT_POOL_SIZE) {
        throw new IllegalArgumentException("The constant pool index must be within the range of [0, " + Constants.MAX_CONSTANT_POOL_SIZE + ")");
    }
    if (charBuffer == null) {
        throw new IllegalArgumentException("charBuffer must not be null");
    }

    // Read the length of the string
    final int length = readUint16(classFileBuffer, constantPoolEntryIndex);

    // Read the string from the class file
    int offset = readUint16(classFileBuffer, constantPoolEntryIndex + 2);
    for (int i = 0; i < length; i++) {
        char c = (char)readUint16(classFileBuffer, offset + i * 2);
        charBuffer[i] = (char)c;
    }

    // Return the string
    return new String(charBuffer, 0, length);
}

final String readUtf(final int constantPoolEntryIndex,final char[] charBuffer) {
    // Obtain the length of the UTF-8 data from the constant pool entry
    int utf8Length = readUnsignedShort(constantPoolEntryIndex, charBuffer);

    // Read the UTF-8 data into the charBuffer
    for (int i = 0; i < utf8Length; i++) {
        charBuffer[i] = readUnsignedByte(constantPoolEntryIndex + 2 + i);
