        int[] constantPool = readConstantPool();
        int tag = constantPool[constantPoolEntryIndex] & TagMask;
        if (tag != Tag.CONSTANT_Utf8) {
            throw new IllegalArgumentException("Invalid constant pool tag: " + tag);
        }
        int offset = constantPool[constantPoolEntryIndex] & OffsetMask;
        int length = readShort(classFileBuffer, offset + 1) & 0xFFFF;
        if (length > charBuffer.length) {
            throw new IllegalArgumentException("charBuffer must be at least " + length + " bytes");
        }
        for (int i = 0; i < length; i++) {
            charBuffer[i] = readChar(classFileBuffer, offset + 3 + 2 * i);
        }
        return new String(charBuffer, 0, length);
    } catch (IOException e) {
        throw new RuntimeException("Failed to read UTF-8 string from constant pool", e);
    }
}

