final String readUtf(final int constantPoolEntryIndex, final char[] charBuffer) {
	if (constantPoolEntryIndex < 0 || constantPoolEntryIndex >= classFileBuffer.length) {
		throw new IllegalArgumentException("Invalid constant pool entry index");
	}

	final int start = classFileBuffer[constantPoolEntryIndex];
	if (start < 0) {
		throw new IllegalStateException("Underlying data corrupted: start offset is negative");
	}

	if (start >= classFileBuffer.length) {
		throw new IllegalStateException("Underlying data corrupted: start offset is larger than the class file's size");
	}

	// Read the length of the string from the class file
	final int length = readLen(start);

	// Check that the length of the string is within the bounds of the provided buffer
	if (length > charBuffer.length) {
		throw new IllegalArgumentException("The provided char buffer is not sufficiently large");
	}

	// Copy the string from the class file into the buffer
	System.arraycopy(classFileBuffer, start, charBuffer, 0, length);

	// Return the string from the buffer
	return new String(charBuffer, 0, length);
}

private int readLen(final int start) {
	// Calculate the position of the string length in the class file
	final int lenPos = start + 1;

	// Check that the position is within the bounds of the class file
	if (lenPos < 0 || lenPos >= classFileBuffer.length) {
		throw new IllegalStateException("Underlying data corrupted: length field is truncated");
	}

	// Read the length of the string from the class file
	final int len = classFileBuffer[lenPos];

	// Check that the length is non-negative
	if (len < 0) {
		throw new IllegalStateException("Underlying data corrupted: length field is negative");
	}

	return len;
}

