  while (!conditionMet && i < stop.getOuterFace().getNodes().length) {
    Node node = start.getOuterFace().getNodes()[i];
    if (predicate.test(node)) {
      conditionMet = true;
      result = Arrays.asList(node, start, stop).stream().collect(new OuterFaceCirculator(), Collectors.groupingBy(Node::getId));
    } else {
      result = new OuterFaceCirculator(start, stop, direction);
    }
    i++;
  }

  return result;
}

