    if (byteArrayValue == null) {
        // If the byte array is null, fill the byte vector with null bytes
        // Calculate the number of null bytes to fill
        int numNullBytes = byteLength - byteOffset;
        // Fill the byte vector with null bytes
        for (int i = 0; i < numNullBytes; i++) {
