    }
    // Check if byteLength is negative, if so, throw IndexOutOfBoundsException
    if (byteLength < 0) {
      throw new IndexOutOfBoundsException("byteLength cannot be negative");
    }
    // Check if byteOffset + byteLength are outside the bounds of byteArray, if so, throw IndexOutOfBoundsException
    if (byteOffset + byteLength > byteArray.length) {
      throw new IndexOutOfBoundsException("byteOffset + byteLength cannot be outside the bounds of byteArray");
    }

    // Set the length of this byte vector
    length = byteLength;
    // Set the capacity of this byte vector
    capacity = length;

    // Put the bytes from byteArray into this byte vector
    for (int i = byteOffset; i < byteOffset + byteLength; i++) {
      data[i] = byteArray[i];
    }

