public ByteVector putByteArray(final byte[] byteArrayValue,final int byteOffset,final int byteLength) {
    if (byteArrayValue == null) {
        for (int i = 0; i < byteLength; i++) {
            put((byte) 0);
        }
        return this;
    } else if (byteArrayValue.length < byteOffset + byteLength) {
        throw new IndexOutOfBoundsException("Insufficient number of bytes in byte array");
    } else {
        for (int i = 0; i < byteLength; i++) {
            put(byteArrayValue[byteOffset + i]);
        }
        return this;
    }
}

public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    if (byteArrayValue == null) {
        throw new NullPointerException("byteArrayValue cannot be null");
    }
    if (byteOffset < 0 || byteOffset > byteArrayValue.length) {
        throw new IndexOutOfBoundsException("byteOffset is out of bounds of the byte array");
    }
    if (byteLength > byteArrayValue.length - byteOffset) {
        throw new IndexOutOfBoundsException("byteLength is too long");
    }

    if (byteArrayValue.length - byteOffset < byteLength) {
        // Insufficient space in the byteArrayValue, so enlarge it
        final byte[] newByteArrayValue = new byte[byteArrayValue.length + byteLength - (byteArrayValue.length - byteOffset)];
        System.arraycopy(byteArrayValue, byteOffset, newByteArrayValue, 0, byteLength);
        byteArrayValue = newByteArrayValue;
    }

    return this;
}

