}

public byte readByte() throws IOException {
    if (bufferPos == buffer.length) {
        buffer = refillBuffer();
        bufferPos = 0;
    }
    return buffer[bufferPos++];
}

private byte[] refillBuffer() throws IOException {
    int numBytesRead = inputStream.read(buffer);
    if (numBytesRead == -1) {
        throw new IOException("No more data available");
    }
    return buffer;
}

public byte readByte() throws IOException {
    if (bufferPosition == buffer.length) {
        refillBuffer();
    }
    return buffer[bufferPosition++];
}

private void refillBuffer() throws IOException {
    int remaining = buffer.length - bufferPosition;
    if (remaining > 0) {
        System.arraycopy(buffer, bufferPosition, buffer, 0, remaining);
    }
    int bytesRead = source.read(buffer, remaining, buffer.length - remaining);
    if (bytesRead == -1) {
        throw new IOException("No more data available.");
    }
    bufferPosition = 0;
}

