        return buffer.get();
    }
    updateBuffer();
    if (buffer.hasRemaining()) {
        return buffer.get();
    }
    throw new IOException("No more data available");
}

private void updateBuffer() throws IOException {
    buffer.clear();
    in.readFully(buffer.asByteBuffer().array());
    buffer.flip();
}

public Action inspect(AtmosphereResource r) {

    if (r.getTransport() == AtmosphereResource.TRANSPORT.WEBSOCKET) {
        r.suspend();
        return Action.CONTINUE;
    } else {
        return Action.CONTINUE;
    }
}

public Action inspect(AtmosphereResource r) {
    // If the AtmosphereResource is null, return CONTINUE
    if (r == null) {
        return Action.CONTINUE;
    }

    // Get the transport type of the AtmosphereResource
    String transport = r.getTransport();

    // If the transport type is "poll" or "websocket", return CONTINUE
    if (transport.equals("poll") || transport.equals("websocket")) {
        return Action.CONTINUE;
    }

    // Suspend the AtmosphereResource
    r.suspend();

    // Return STOP
    return Action.STOP;
}

@Override
public Action inspect(AtmosphereResource r) {
    switch (r.getTransport()) {
        case LONG_POLLING:
        case SSE:
            if (r.isResponsive()) {
                return Action.CONTINUE;
            } else {
                r.suspend();
                return Action.TERMINATE;
            }
        default:
            return Action.CONTINUE;
    }
}

public Action inspect(AtmosphereResource r) {
   if (r.getTransport().equals(AtmosphereResource.TRANSPORT.AJAX)) {
      r.suspend();
   }
