}

public Action inspect(AtmosphereResource r) {
  // Return a CONTINUE Action if the resource is not valid or unable to be suspended
  if (!r.isValid() || !r.getTransport().isSupported()) {
    return Action.CONTINUE;
  }

  // Try to suspend the resource if it is possible and beneficial to do so
  if (r.suspendIfNecessary()) {
    return Action.CONTINUE;
  }

  // If the resource cannot be suspended, throw an exception
  throw new AtmosphereResourceSuspensionException();
}

