    // Check if the input is valid
    if (tour != null && graph != null) {
        // Iterate over the edges in the tour
        for (E edge : tour) {
            // Check if the edge is part of the graph
            if (graph.containsEdge(edge)) {
                // Add the edge to the path
                path.addEdge(edge);
            } else {
                // Throw an exception if the edge is not part of the graph
                throw new IllegalArgumentException("The edge " + edge + " is not part of the graph");
            }
        }
    } else {
        // Throw an exception if the input is null
        throw new NullPointerException("The input set of edges or graph is null");
    }

    return path;
}

