private static string unescapeId(string input) {
    StringBuilder sb = new StringBuilder();
    for (int i = 0; i < input.Length; i++) {
        char c = input[i];
        if (c == '\\') {
            c = input[++i];
            switch (c) {
                case 'n':
                    c = '\n';
                    break;
                case 'r':
                    c = '\r';
                    break;
                case 't':
                    c = '\t';
                    break;
                case '\\':
                    c = '\\';
                    break;
            }
        }
        sb.Append(c);
    }
    return sb.ToString();
}

private String unescapeId(String input) {
    StringBuilder output = new StringBuilder();
    for (int i = 0; i < input.length(); ++i) {
        char c = input.charAt(i);
        if (c == '\\') {
            // Handle escape character
            if (i + 1 >= input.length()) {
                throw new IllegalArgumentException("Input string has incomplete escape sequence");
            }
            char escapedChar = input.charAt(i + 1);
            if (escapedChar == 'n') {
                // Newline
                output.append("\n");
            } else if (escapedChar == 't') {
                // Tab
                output.append("\t");
            } else if (escapedChar == 'r') {
                // Carriage return
                output.append("\r");
            } else if (escapedChar == 'b') {
                // Backspace
                output.append("\b");
            } else if (escapedChar == 'f') {
                // Form feed
                output.append("\f");
            } else if (escapedChar == '\\') {
                // Escape character
                output.append("\\");
            } else if (escapedChar == '\n') {
                // Escaped newline
                output.append("\n");
            } else {
                // Handle other escape sequences
                output.append("\\").append(escapedChar);
            }
            // Skip the next character as it has been processed
            ++i;
        } else {
            output.append(c);
        }
    }
    return output.toString();
}

private static String unescapeId(String input) {
  // Check if input is null
  if (input == null) {
