  // Iterate over input characters
  for (int i = 0; i < input.length(); i++) {
    char c = input.charAt(i);
    // If current character is an escaped character, skip it and advance i by 2
    if (c == '\\') {
      i++;
      c = input.charAt(i);
    }
    // Append character to output
    output.append(c);
  }
  // Return unescaped output
  return output.toString();
}

private String unescapeId(String input) {
    String output = "";
    for (int i = 0; i < input.length(); i++) {
        char c = input.charAt(i);
        if (c != '\\') {
            output += c;
        } else {
            i++;
            c = input.charAt(i);
            switch (c) {
                case 'n':
                    output += "\n";
                    break;
                case 't':
                    output += "\t";
                    break;
                case '`':
                    output += "`";
                    break;
                case '\\':
                    output += "\\";
                    break;
                default:
                    output += c;
            }
        }
    }
    return output;
}

private String unescapeId(String input) {

    // Safety checks
    if (input == null) {
        throw new IllegalArgumentException("Input argument cannot be null");
    }

    StringBuilder sb = new StringBuilder(input.length());
    int index = 0;
    while (index < input.length()) {
        if (input.charAt(index) == '\\') {
            // We have an escaped character
            index++;
            if (index >= input.length()) {
                throw new IllegalArgumentException("Incomplete escape sequence");
            }
            switch (input.charAt(index)) {
                case '.':
                    sb.append('.');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    throw new IllegalArgumentException("Unknown escape sequence: " + input.charAt(index));
            }
        } else {
            sb.append(input.charAt(index));
        }
        index++;
    }

    return sb.toString();
}

