    }
    if (minLabel < 0 || minLabel >= bucketsByLabel.size()) {
        throw new IllegalArgumentException("Min label must be in the range of bucket labels");
    }

    // Get the buckets to move vertices from and to
    Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
    Set<Integer> destBucket = bucketsByLabel.get(0);

    // Move all vertices from the source bucket to the destination bucket
    destBucket.addAll(sourceBucket);
    sourceBucket.clear();

    // Update the labels of the affected vertices
    for (int vertex : destBucket) {
        labels.set(vertex, 0);
    }
}

private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    // Find the minimum label
    int minLabelIndex = minLabel - 1;

    // Get the current bucket with the minimum label
    Set<Integer> minBucket = bucketsByLabel.get(minLabelIndex);

    // Clear the minimum bucket
    minBucket.clear();

    // Loop through all the vertices
    for (int vertex : labels) {
        // If the vertex has the minimum label, add it back to the 0 bucket
        if (vertex == minLabel) {
            bucketsByLabel.get(0).add(vertex);
        }
    }

    // Update the labeling
    labels.set(0, minLabel);
}

