private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) throw new NullPointerException("Node is null");
    // First, unlink the next node, if present
    if (node.next != null) {
        if (unlink(node.next)) {
            // If the next node was unlinked, make the previous node point to its next node
            node.next = node.next.next;
        }
    }
    // If the node has no next node, make the prev node point to its next node
    if (node.previous != null) {
        node.previous.next = node.next;
    }
    return true;
}

private boolean unlink(ListNodeImpl<E> node) {
    if (node == null) {
        throw new IllegalArgumentException("Cannot unlink a null node");
    }

    boolean isUnlinked = false;
    ListNodeImpl<E> previous = node.getPrevious();
    ListNodeImpl<E> next = node.getNext();

    if (previous != null) {
        previous.setNext(next);
        isUnlinked = true;
    }

    if (next != null) {
        next.setPrevious(previous);
        isUnlinked = true;
    }

    node.setPrevious(null);
    node.setNext(null);

    return isUnlinked;
}

