    if (str == null || leadingCharacter == 0) {
        return str;
    }

    int startIndex = 0;
    for (int i = 0; i < str.length(); i++) {
        if (str.charAt(i) != leadingCharacter) {
            startIndex = i;
            break;
        }
    }

    int endIndex = str.length() - 1;
    for (int i = str.length() - 1; i >= startIndex; i--) {
        if (str.charAt(i) != leadingCharacter) {
            endIndex = i;
            break;
        }
    }

    return str.substring(startIndex, endIndex + 1);
}

