private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // initialize result variables
    List<Integer> suffixSum = new ArrayList<>();
    long sum = 0;

    // iterate over the bounds list
    for (int i = 0; i < bounds.size(); i++) {
      // compute the suffix sum of the current element
      int currentSuffixSum = 0;
      for (int j = i; j < bounds.size(); j++) {
        currentSuffixSum += bounds.get(j);
      }
      // add the current suffix sum to the suffix sum list
      suffixSum.add(currentSuffixSum);
      // accumulate the sum of all elements in the original list
      sum += bounds.get(i);
    }

    // return the computed suffix sum list and the sum of all elements
    return new Pair<>(suffixSum, sum);
  }

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    // Check if the input list is valid
    if (bounds == null || bounds.isEmpty()) {
        throw new IllegalArgumentException("Input list of bounds is null or empty");
    }

    // Initialize the suffix sum list and the total sum
    List<Integer> suffixSum = new ArrayList<>(bounds.size());
    long totalSum = 0L;

    // Compute the suffix sum and the total sum
    for (int i = 0; i < bounds.size(); i++) {
        suffixSum.add(totalSum + bounds.get(i));
        totalSum += bounds.get(i);
    }

    // Return the computed suffix sum and the total sum
    return Pair.of(suffixSum, totalSum);
}

public static <V> void reverse(V[] arr, int from, int to) {
    if (arr == null) throw new NullPointerException("arr cannot be null");
    if (from < 0 || from >= arr.length) throw new IndexOutOfBoundsException("from index is out of bounds");
    if (to < 0 || to >= arr.length) throw new IndexOutOfBoundsException("to index is out of bounds");
    if (from >= to) throw new IllegalArgumentException("from index must be smaller than to index");

    for (int i = 0; i < (to - from) / 2; i++) {
        swap(arr, from + i, arr.length - 1 - i);
    }
}

private static <V> void swap(V[] arr, int i, int j) {
    V tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
}

public static void reverse(int[] arr, int from, int to) {
    // swap the elements in the range with the corresponding elements on the other side of the reversed array
    for (int i = 0; i < (to - from) / 2; i++) {
        int tmp = arr[from + i];
        arr[from + i] = arr[to - i];
        arr[to - i] = tmp;
