    ListNode<E> head = list.getHead();

    // If the head is null, return
    if (head == null) {
        return;
    }

    // Initialize the previous node to null
    ListNode<E> previous = null;

    // Iterate through the list and remove each node
    do {
        // Get the current node
        ListNode<E> current = head;//head.getNode();

        // If the current node is not null, update the previous node to the current node
        if (current != null) {
            previous = current;
        }

        // Remove the current node from the list
        removeListNode(current);

        // Add the current node to this list
        addListNode(current);
    } while (previous != null);
}

