}

List<Pair<List<Pair<Integer,Integer>>,E>> computeGlobalSeparatorList() {
    List<Pair<List<Pair<Integer,Integer>>,E>> separatorList = new ArrayList<>();

    // Iterate over all edges in the graph
    for (E edge : graph.getEdges()) {
        // Initialize the local list of separators for this edge
        List<Pair<Integer,Integer>> localSeparators = new ArrayList<>();

        // Iterate over the neighbours of this edge
        for (E neighbourEdge : graph.getNeighbors(edge)) {
            // Compute the minimal separators for this edge and this neighbour
            localSeparators.addAll(computeMinimalSeparators(edge, neighbourEdge));
        }

        // Add the local list of separators to the global list
        separatorList.add(new Pair<>(localSeparators, edge));
    }

    return separatorList;
}

