public List<Pair<List<Integer>, E>> computeGlobalSeparatorList(Graph <V,E> graph) {
    List<Pair<List<Integer>, E>> separatorList = new ArrayList<>();
    for (E e : graph.edges()) {
        List<Pair<Integer, Integer>> neighbors = graph.neighbors(e);
        List<Integer> minimalSeparators = computeMinimalSeparators(e, neighbors);
        separatorList.add(new Pair<List<Integer>, E>(minimalSeparators, e));
    }
    return separatorList;
}

private List<Integer> computeMinimalSeparators(E edge, List<Pair<Integer, Integer>> neighbors) {
    List<Integer> minimalSeparators = new ArrayList<>();
    for (Pair<Integer, Integer> neighbor : neighbors) {
        int separator = computeSeparator(edge, neighbor);
        if (!minimalSeparators.contains(separator)) {
            minimalSeparators.add(separator);
        }
    }
    return minimalSeparators;
}

private int computeSeparator(E edge, Pair<Integer, Integer> neighbor) {
    int i = 0;
    while (i < edge.length() && edge.charAt(i) == neighbor.getFirst()) {
        i++;
    }
    return i;
}

