public ByteVector putInt(final int intValue) {
    // Check if the byte vector needs to be enlarged
    if (size() + 4 > capacity()) {
        resize(2 * (size() + 4));
    }
    // Ensure the int is of the correct endianness
    int val = intValue << 24 | intValue >>> 24;
    val = val << 16 | val >>> 16;
    val = val << 8 | val >>> 8;
    // Write the int to the byte vector
    put(offset++, (byte) val);
    put(offset++, (byte) (val >>> 8));
    put(offset++, (byte) (val >>> 16));
    put(offset++, (byte) (val >>> 24));
    return this;
}

