}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if all neighbors of each vertex in the subgraph are also in the subgraph
    for (V vertex : vertices) {
        Set<V> neighbors = graph.adjacentVertices(vertex);
        if (!neighbors.containsAll(vertices)) {
            return false;
        }
    }
    return true;
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the graph is null or the vertex set is empty
    if (graph == null || vertices.isEmpty()) {
        return false;
    }

    // Initialize a set to store the vertices that are adjacent to at least one other vertex in the graph
    Set<V> partialClique = new HashSet<>();

    // Iterate over each vertex in the vertex set
    for (V vertex : vertices) {
        // If the vertex has no edges in the graph, it cannot be a part of a clique
        if (graph.getEdges(vertex).isEmpty()) {
            return false;
        }

        // Add the vertex to the partial clique set if it has at least one edge to another vertex in the graph
        partialClique.add(vertex);
    }

    // If the partial clique set is equal to the original vertex set, then the subgraph is complete (i.e. a clique)
    return partialClique.size() == vertices.size();
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    /*
     * Step 1: Check if the input graph is null or empty.
     */
    if (graph == null || graph.isEmpty()) {
        throw new IllegalArgumentException("The input graph must not be null or empty.");
    }

    /*
     * Step 2: Check if the input vertices set is null or empty.
     */
    if (vertices == null || vertices.isEmpty()) {
        throw new IllegalArgumentException("The input vertices set must not be null or empty.");
    }

    /*
     * Step 3: Check if all the vertices in the input graph are in the input vertices set.
     */
    for (V vertex : graph.vertexSet()) {
        if (!vertices.contains(vertex)) {
            return false;
        }
    }

    /*
     * Step 4: Check if the subgraph induced by the input vertices is complete, i.e., a clique.
     */
    Graph<V, E> inducedSubgraph = graph.subgraph(vertices);
    for (V vertex : inducedSubgraph.vertexSet()) {
        for (V neighbor : inducedSubgraph.neighborhood(vertex)) {
            if (!inducedSubgraph.containsEdge(vertex, neighbor)) {
                return false;
            }
        }
    }

    /*
     * Step 5: The subgraph is complete, so it is a clique.
     */
    return true;
}

