    return lowerBounds;
}

private static List<Integer> computeLowerBounds(final List<K> keys) {
    final Set<Integer> uniqueKeys = new HashSet<>(keys);
    final int numOfKeys = uniqueKeys.size();

    final List<Integer> lowerBounds = new ArrayList<>(numOfKeys);

    for (int i = 0; i < numOfKeys; i++) {
        int current = -1;
        for (final K key : keys) {
            final int idx = uniqueKeys.indexOf(key);
            if (idx > current) {
                current = idx;
            }
        }
        lowerBounds.add(current);
    }

    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
