    List<Integer> lowerBounds = new ArrayList<>();

    // Iterate over the list of keys
    for (K key : keys) {
      // For each key, find the maximum lower bound among all the keys that are smaller than it
      int maxLowerBound = 0;
      for (K smallerKey : keys) {
        if (smallerKey.compareTo(key) < 0) {
          maxLowerBound = Math.max(maxLowerBound, getKeyLowerBound(smallerKey));
        }
      }
      lowerBounds.add(maxLowerBound);
    }

