                    isPrimitive = true;
                    break;
                }
            }
            if (!isPrimitive) {
                throw new IllegalArgumentException("Descriptor is not a valid primitive type: " + descriptor);
            }
        } else {
            throw new IllegalArgumentException("Descriptor is not a valid descriptor string: " + descriptor);
        }
    } else if (!PRIMITIVE_TYPES.contains(descriptor)) {
        throw new IllegalArgumentException("Descriptor is not a valid primitive type: " + descriptor);
    }

    for (int i = 0; i < descriptor.length(); ++i) {
        if (descriptor.charAt(i) == '[') {
            ++i;
        } else if (descriptor.charAt(i) == 'L') {
            i = descriptor.length();
        } else {
            break;
        }
    }

    String primitiveType = descriptor.substring(0, descriptor.length() - 1);
    switch (primitiveType) {
