private void pop(final String descriptor) {
    // First, check if the given descriptor is null or empty
    if (descriptor == null || descriptor.isEmpty()) {
        throw new IllegalArgumentException("Descriptor cannot be null or empty");
    }

    // If the descriptor is a method descriptor, parse it to get the argument types
    String[] argumentTypeDescriptors = null;
    if (descriptor.startsWith("(")) {
        int closingParenIndex = descriptor.indexOf(")");
        if (closingParenIndex == -1) {
            throw new IllegalArgumentException("Method descriptor must have a closing parentheses");
        }
        argumentTypeDescriptors = descriptor.substring(1, closingParenIndex).split(",");
    }

    // Pop the appropriate number of arguments from the output frame stack
    int numOfArgsToPop = (argumentTypeDescriptors != null) ? argumentTypeDescriptors.length : 1;
    for (int i = 0; i < numOfArgsToPop; i++) {
        Type argumentType = (argumentTypeDescriptors != null) ? Type.getType(argumentTypeDescriptors[i]) : Type.getType(descriptor);
        pop(argumentType);
    }
