private void pop(final String descriptor) {
    // Check if the descriptor is not null
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }

    // Check if the descriptor has a length of at least 1
    if (descriptor.length() < 1) {
        throw new IllegalArgumentException("Descriptor must have at least one character");
    }

    // Check if the first character of the descriptor is a valid type descriptor
    if (!isValidTypeDescriptor(descriptor.charAt(0))) {
