    }

    // Check if the second character of the descriptor is a valid method descriptor
    if (descriptor.length() > 1 && !isValidMethodDescriptor(descriptor.charAt(1))) {
        throw new IllegalArgumentException("Descriptor must end with a valid method descriptor");
    }

    // Pop the abstract types from the output frame stack based on the given descriptor
    final char firstChar = descriptor.charAt(0);
    final char secondChar = descriptor.length() > 1 ? descriptor.charAt(1) : '\0';
