public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path or relative path is null");
    }

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    if (pathParts.length == 0 || relativePathParts.length == 0) {
        throw new IllegalArgumentException("Path or relative path is empty");
    }

    StringBuilder builder = new StringBuilder();
    for (String pathPart : pathParts) {
        if (pathPart.isEmpty()) {
            continue;
        }
        builder.append(pathPart).append("/");
    }

    for (String relativePathPart : relativePathParts) {
        if (relativePathPart.isEmpty()) {
            continue;
        }

        if (relativePathPart.startsWith("..")) {
            int index = builder.lastIndexOf("/");
            if (index != -1) {
                builder.delete(index, builder.length());
            }
        } else if (!relativePathPart.startsWith(".")) {
            builder.append(relativePathPart).append("/");
        }
    }

    return builder.toString();
}

public static String applyRelativePath(String path, String relativePath) {
    String[] pathComponents = path.split("/");
    String[] relativePathComponents = relativePath.split("/");

    // Check if the path is absolute
    if (pathComponents[0].isEmpty()) {
        throw new IllegalArgumentException("Path must be absolute");
    }

    // Check if the relative path is absolute
    if (relativePathComponents[0].isEmpty()) {
        throw new IllegalArgumentException("Relative path must be relative");
    }

    // Check if the path and relative path have the same number of components
    if (pathComponents.length != relativePathComponents.length) {
        throw new IllegalArgumentException("Path and relative path must have the same number of components");
    }

    // Apply the relative path to the path
    for (int i = 0; i < pathComponents.length; i++) {
        if (!relativePathComponents[i].isEmpty()) {
            pathComponents[i] = relativePathComponents[i];
        }
    }

    return String.join("/", pathComponents);
}

public static String applyRelativePath(String path, String relativePath) {
    // Check if the path and relativePath are null or empty
    if (path == null || relativePath == null || path.isEmpty() || relativePath.isEmpty()) {
        throw new IllegalArgumentException("Path and relativePath cannot be null or empty");
    }

    // Split the path and relativePath into their corresponding parts
    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    // Check if the path and relativePath have an equal number of parts
    if (pathParts.length != relativePathParts.length) {
        throw new IllegalArgumentException("Path and relativePath must have an equal number of parts");
    }

    // Create a new array to store the result
    String[] result = new String[pathParts.length];

    // Iterate through the path and relativePath parts and apply the relativePath parts to the result
    for (int i = 0; i < pathParts.length; i++) {
        if (relativePathParts[i].equals(".")) {
            result[i] = pathParts[i];
        } else if (relativePathParts[i].equals("..")) {
            result[i] = "..";
        } else {
            result[i] = pathParts[i] + relativePathParts[i];
        }
    }

    // Join the result parts into a single string and return it
    return String.join("/", result);
}

public static String applyRelativePath(String path, String relativePath) {
    if (path == null || relativePath == null) {
        throw new IllegalArgumentException("Path and relativePath cannot be null");
    }

    path = path.replace("\\", "/");
    relativePath = relativePath.replace("\\", "/");

    String[] pathParts = path.split("/");
    String[] relativePathParts = relativePath.split("/");

    String resultPath = "";
    for (String part : pathParts) {
        if (part.equals("..")) {
            if (resultPath.equals("")) {
                // If we reach the start of the path and there is a ".." in the relativePath,
                // return an exception because we cannot go further up the directory tree
                throw new IllegalArgumentException("Path cannot be resolved because there is a '..' at the start of the path");
            } else {
                // Otherwise, remove the last part of the resultPath
                // and add a ".." to indicate going back one directory
                resultPath = resultPath.substring(0, resultPath.lastIndexOf("/") + 1) + "..";
            }
        } else {
            // If the part is not "..", add the part to the resultPath
            resultPath += part + "/";
        }
    }

    // Add the relativePath at the end of the resultPath
    resultPath += relativePath;

    return resultPath;
}

