  if (node.isVirtual()) {
    // If the current node is virtual, get the real counterpart
    Node realNode = node.getRealCounterpart();
    // Check if the next node is virtual
    if (realNode.getNext().isVirtual()) {
      // If the next node is virtual, get its real counterpart
      Node nextRealNode = realNode.getNext().getRealCounterpart();
      // Create an edge between the real nodes
      Edge edge = new Edge(realNode, nextRealNode);
      return edge;
    } else {
      // If the next node is real, create an edge between the real nodes
      Edge edge = new Edge(realNode, realNode.getNext());
      return edge;
    }
  } else {
    // If the current node is real, get the next node
    Node nextNode = node.getNext();
    // Check if the next node is virtual
    if (nextNode.isVirtual()) {
      // If the next node is virtual, get its real counterpart
      Node nextRealNode = nextNode.getRealCounterpart();
      // Create an edge between the real nodes
      Edge edge = new Edge(node, nextRealNode);
      return edge;
    } else {
      // If the next node is real, create an edge between the two nodes
      Edge edge = new Edge(node, nextNode);
      return edge;
    }
  }
}

