public int readRawVarint32() throws IOException {
    int result = 0;
    int offset = 0;
    int b;

    do {
        b = in.read() & 0xff;
        result |= (b & 0x7f) << offset;
        offset += 7;
    } while (b >= 0x80);

    return result;
}

