public ByteVector put11(final int byteValue1,final int byteValue2){
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("Invalid byte values");
    }

    if (this.bytes == null) {
        this.bytes = new byte[2];
    }

    if (this.bytes.length < this.size + 2) {
        byte[] newBytes = new byte[this.bytes.length * 2];
        System.arraycopy(this.bytes, 0, newBytes, 0, this.size);
        this.bytes = newBytes;
    }

    this.bytes[this.size] = (byte) byteValue1;
    this.bytes[this.size + 1] = (byte) byteValue2;
    this.size += 2;

    return this;
}

public void put11(byte byteValue1, byte byteValue2) {
    if (byteValue1 < 0 || byteValue1 > 255 || byteValue2 < 0 || byteValue2 > 255) {
        throw new IllegalArgumentException("Invalid byte value");
    }
    if (this.capacity < this.length + 2) {
        this.ensureCapacity(this.length + 2);
    }
    this.buffer[this.length++] = (byte) byteValue1;
    this.buffer[this.length++] = (byte) byteValue2;
}

final ByteVector put11(final int byteValue1, final int byteValue2) {
    // Check if the byte vector is not null
    if (this.byteVector == null) {
        throw new IllegalArgumentException("The byte vector is null");
    }
    // Check if the byte vector is not already enlarged
    if (this.byteVector.length < 2) {
        enlarge();
    }
    // Set the first byte
    this.byteVector[0] = byteValue1;
    // Set the second byte
    this.byteVector[1] = byteValue2;
    // Return the byte vector
    return this.byteVector;
}

public final ByteVector put11(byteValue1, byteValue2) {
  if (byteValue1 < 0 || byteValue1 > 255) {
    throw new IllegalArgumentException("byteValue1 must be between 0 and 255");
  }
  if (byteValue2 < 0 || byteValue2 > 255) {
    throw new IllegalArgumentException("byteValue2 must be between 0 and 255");
  }
  ensureCapacity(position + 2);
  byte[] bytes = getBytes();
  bytes[position] = (byte) (byteValue1 & 0xFF);
  bytes[position + 1] = (byte) (byteValue2 & 0xFF);
  position += 2;
  return this;
}

