public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("File cannot be null");
    }
    if (!file.exists()) {
        throw new FileNotFoundException("File not found");
    }
    if (!file.isFile()) {
        throw new IllegalArgumentException("File must be a regular file");
    }
    if (timeRanges == null) {
        throw new IllegalArgumentException("Time ranges cannot be null");
    }
    if (timeRanges.isEmpty()) {
        throw new IllegalArgumentException("Time ranges cannot be empty");
    }

    // Check if the time ranges are sorted
    if (!isSortedByStartTimeWithNoOverlap(timeRanges)) {
        throw new IllegalArgumentException("Time ranges must be sorted by start time");
    }

    // Load the thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = reader.readLine()) != null) {
            ThreadSnapshot threadSnapshot = parseThreadSnapshot(line);
            if (threadSnapshot != null) {
                if (isTimeWithinRange(threadSnapshot.getTime(), timeRanges)) {
                    threadSnapshots.add(threadSnapshot);
                }
            }
        }
    }

    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Check for invalid input parameters
    if (file == null || timeRanges == null || timeRanges.isEmpty()) {
        throw new IllegalArgumentException("File and time ranges cannot be null or empty");
    }

    // Initialize the list of thread snapshots
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();

    // Parse the file and find the thread snapshots in the specified time ranges
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        String line = reader.readLine();
        while (line != null) {
            ThreadSnapshot snapshot = parseThreadSnapshot(line);
            if (snapshot != null) {
                // Check if the snapshot is in the specified time range
                if (timeRanges.stream().anyMatch(s -> s.contains(snapshot.getTimestamp()))) {
                    threadSnapshots.add(snapshot);
                }
            }
            line = reader.readLine();
        }
    } catch (IOException e) {
        throw new IOException("Error reading file", e);
    }

    // Return the list of thread snapshots
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    ProfileAnalyzeTimeRange range = timeRanges.get(0);
    int startIndex = findStartIndex(file, range);
    int endIndex = findEndIndex(file, range);
    for (int i = startIndex; i <= endIndex; i++) {
        snapshots.add(parse(file, i));
    }
    return snapshots;
}

private static int findStartIndex(File file, ProfileAnalyzeTimeRange timeRange) throws IOException {
    String line = null;
    try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
        while ((line = reader.readLine()) != null) {
            if (isWithinTimeRange(line, timeRange)) {
                return findStartIndex(reader, line);
            }
        }
    }
    return -1;
}

public List<ThreadSnapshot> loadWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null || timeRanges == null) {
        throw new IllegalArgumentException("The file and timeRanges parameters must not be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("The input file does not exist or is not a valid file");
    }
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    long totalSize = file.length();
    byte[] buffer = new byte[1000];
    try (FileInputStream fis = new FileInputStream(file)) {
        for (int i = 0; i < timeRanges.size(); i++) {
            ProfileAnalyzeTimeRange timeRange = timeRanges.get(i);
            long startTime = timeRange.getStartTime();
            long endTime = timeRange.getEndTime();
            ThreadSnapshot threadSnapshot = null;
            long totalBytesRead = 0;
            while (totalBytesRead < totalSize && startTime >= 0 && endTime >= 0) {
                int bytesRead = fis.read(buffer);
                String data = new String(buffer, 0, bytesRead);
                if (startTime <= 0 && endTime <= 0) {
                    continue;
                }
                threadSnapshot = ThreadSnapshot.parseFromString(data);
                if (threadSnapshot != null) {
                    threadSnapshots.add(threadSnapshot);
                    totalBytesRead += bytesRead;
                }
            }
        }
    } catch (IOException e) {
        throw new IOException("Error reading from file", e);
    }
    return threadSnapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    if (file != null && timeRanges != null && !timeRanges.isEmpty()) {
        // Read the thread snapshots from the file
        String contents = new String(Files.readAllBytes(file.toPath()));
        // Parse the contents of the file to extract the thread snapshots
        Pattern threadSnapshotPattern = Pattern.compile("[0-9]+\\t(.*?)\\stalloc");
        Matcher threadSnapshotMatcher = threadSnapshotPattern.matcher(contents);
        while (threadSnapshotMatcher.find()) {
            ThreadSnapshot threadSnapshot = new ThreadSnapshot();
            String[] threadInfo = threadSnapshotMatcher.group(1).split("\\t");
            threadSnapshot.setTid(Integer.parseInt(threadInfo[0]));
            threadSnapshot.setAlloc(Long.parseLong(threadInfo[1]));
            threadSnapshots.add(threadSnapshot);
        }
        //Filter the thread snapshots based on the time ranges provided by the client
        List<ThreadSnapshot> filteredThreadSnapshots = threadSnapshots.stream()
                .filter(s -> s.getAlloc() <= timeRanges.get(timeRanges.size()-1).getEndTime())
                .collect(Collectors.toList());
        return filteredThreadSnapshots;
    }
    return new ArrayList<>();
}
